import random
random.seed(42)
draws = [set(random.sample(range(1, 50), 6)) for _ in range(50)]
last = {}
for i, d in enumerate(draws):
    for n in d:
        last[n] = i
gaps = sorted(((49 - last.get(n, -1), n) for n in range(1, 50)), reverse=True)[:5]
print('SIMULATED longest gaps (fixed seed, teaching only):')
for gap, n in gaps:
    print('number', n, 'draws since last appearance:', gap)

glossary = {'draw': 'one random selection', 'matrix': 'pool and count for a game', 'tier': 'prize level by matches', 'frequency': 'count in a chosen window', 'rollover': 'unwon jackpot carried forward', 'expected value': 'long-run average per ticket'}
print('suite glossary (alphabetical):')
for term in sorted(glossary):
    print(term, '-', glossary[term])
print('terms defined:', len(glossary))
